function firstWord(str) {
  // return everything before the first space
}

exercises.solution:
function firstWord(str) {
  const i = str.indexOf(' ')
  return i === -1 ? str : str.slice(0, i)
}

exercises.starter:
function truncate(str, maxLength) {
  // add an ellipsis only when str exceeds maxLength
}

exercises.solution:
function truncate(str, maxLength) {
  return str.length <= maxLength ? str : `${str.slice(0, maxLength)}...`
}
